logger = logging.getLogger(__name__)
logger.addHandler(logging.NullHandler())


class L1L2BIPCollectorBase(Using("tool_executor"), Collector):
    """
    Base class to Start , Stop and Collect L1/L2 BIP logs on given configuration.
    """

    def __init__(
            self,
            collector,
            **kwargs):
        super(L1L2BIPCollectorBase, self).__init__(**kwargs)

        self._collector = collector
        self.add_prerequisite(self._collector)

    @property
    def collector(self):
        return self._collector

    def __getattr__(self, name):
        return getattr(self._collector, name)

    def _collect(self, target_dir):
        self._collector._collect(target_dir=target_dir)


class ScriptInstallationMixin(Using("file_putter")):
    """
    Adds Script upload, setup and teardown steps. This class expects following parameters which should be
    available/initialized by mixed-in class:
    self._tool_executor : tool executor for command execution
    self.script_paths : local scripts path need to be uploaded as self._script_dir
    self._build_setup_command() : provides commands need to be run post upload
    self._build_teardown_command(): provides commands need to be run in tear down
    """

    def __init__(
            self,
            script_dir=None,
            **kwargs):
        super(ScriptInstallationMixin, self).__init__(**kwargs)
        self._script_dir = "/ffs/run/config/scripts" if script_dir is None else script_dir

    def _setup(self):

        self._tool_executor.execute(
            "mkdir -p {script_dir}".format(script_dir=self._script_dir).encode())
        for script_path in self.script_paths:
            script_name = os.path.basename(script_path)
            self._file_putter.put_file(source_path=script_path,
                                       target_path="{script_dir}/{script_name}".format(script_dir=self._script_dir,
                                                                                       script_name=script_name))
            self._tool_executor.execute(
                "chmod +x {script_dir}/{script_name}".format(script_dir=self._script_dir,
                                                             script_name=script_name).encode())
        self._tool_executor.execute(self._build_setup_command())

    def _teardown(self):
        teardown_command = self._build_teardown_command()
        if teardown_command is not None:
            self._tool_executor.execute(teardown_command)
        for script_path in self.script_paths:
            script_name = os.path.basename(script_path)
            self._tool_executor.execute(
                "rm -f {script_dir}/{script_name}".format(script_dir=self._script_dir,
                                                          script_name=script_name).encode())

    @abstractmethod
    def _build_setup_command(self):
        pass

    def _build_teardown_command(self):
        return None


class L1L2BIPCollector(ScriptInstallationMixin, L1L2BIPCollectorBase):
    """
    To Start , Stop and Collect L1/L2 BIP logs on given configuration.
    """

    def __init__(
            self,
            mirroring_mode=None,
            gnb_mirroring_path=None,
            gnb_mirroring_config_path=None,
            enable_syscom_mirroring=None,
            mirror_capacity_units=None,
            carrier_aggregation=None,
            **kwargs):
        super(L1L2BIPCollector, self).__init__(**kwargs)
        self._mirroring_mode = "manual" if mirroring_mode is None else mirroring_mode
        self._gnb_mirroring_path = "/opt/gnbmirroring/gnbMirroring.sh" \
            if gnb_mirroring_path is None else gnb_mirroring_path
        self._gnb_mirroring_config_path = "/opt/gnbmirroring/gnbMirroringConfig.sh" \
            if gnb_mirroring_config_path is None else gnb_mirroring_config_path
        self._enable_syscom_mirroring = True if enable_syscom_mirroring is None else enable_syscom_mirroring
        self._mirror_capacity_units = [1] if mirror_capacity_units is None else eval(str(mirror_capacity_units))
        self._carrier_aggregation = True if carrier_aggregation is None else carrier_aggregation
        self.script_paths = [self._gnb_mirroring_path, self._gnb_mirroring_config_path]

    def _build_setup_command(self):
        _gnbmirroring_script = os.path.basename(self._gnb_mirroring_path)
        self.bip_mirror_args = (
            " ".join(
                "--mirror_abil_{index}={value}".format(
                    index=index,
                    value=str(index in self._mirror_capacity_units).lower())
                for index in range(1, 4)))
        logger.debug("getting bip mirror info " + self.bip_mirror_args)

        return ("cd {script_dir}; sh {script_name} "
                "--mirroring_mode={mirroring_mode} "
                "--enable_syscom_mirroring={enable_syscom_mirroring} "
                "{bip_mirror_args} "
                "--carrier_aggregation={carrier_aggregation}".
                format(script_dir=self._script_dir,
                       script_name=_gnbmirroring_script,
                       mirroring_mode=self._mirroring_mode,
                       enable_syscom_mirroring=self._enable_syscom_mirroring,
                       bip_mirror_args=self.bip_mirror_args,
                       carrier_aggregation=self._carrier_aggregation).encode())


class ASODL1L2BIPCollector(ScriptInstallationMixin, L1L2BIPCollectorBase):
    """
    To Start , Stop and Collect ASOD L1/L2 BIP logs on given configuration.
    """

    def __init__(
            self,
            asod_mirroring_path=None,
            **kwargs):
        super(ASODL1L2BIPCollector, self).__init__(**kwargs)

        if asod_mirroring_path is None:
            asod_mirroring_path = "/opt/gnbmirroring/ASOD_mirror.sh"
        self._asod_mirroring_path = asod_mirroring_path
        self.script_paths = [self._asod_mirroring_path]

    def _build_setup_command(self):
        _asodmirroring_script = os.path.basename(self._asod_mirroring_path)

        return ("cd {script_dir}; sh {script_name} ".format(
            script_dir=self._script_dir,
            script_name=_asodmirroring_script).encode())


class GenericL1L2BIPCollector(L1L2BIPCollectorBase):
    """
    To Start , Stop and Collect Generic L1/L2 BIP logs on given configuration.
    """

    def __init__(self,
                 setup_commands,
                 teardown_commands=None,
                 **kwargs):
        super(GenericL1L2BIPCollector, self).__init__(**kwargs)
        self._setup_commands = setup_commands
        self._teardown_commands = teardown_commands if teardown_commands else []

    def _setup(self):
        for command in self._setup_commands:
            self._tool_executor.execute(command.encode())

    def _teardown(self):
        for command in self._teardown_commands:
            self._tool_executor.execute(command.encode())


class InterfaceMirroringL1L2BIPCollectorBase(Using("local_executor"), StartableCollector):
    def __init__(self,
                 interface="L1-L2",
                 timeout=60,
                 remove_zip_file=True,
                 nr_phy_cell_ids=None,
                 nr_cell_dns=None,
                 **kwargs):
        super(InterfaceMirroringL1L2BIPCollectorBase, self).__init__(**kwargs)
        self._timeout = timeout
        self._interface_mirroring_start_params = {'interface': interface, 'timeout': self._timeout, 'mirroring_time': 0}
        if nr_cell_dns is not None:
            self._interface_mirroring_start_params['nr_cell_dns'] = nr_cell_dns
        self._remove_zip_file = remove_zip_file
        self._nr_phy_cell_ids = nr_phy_cell_ids

    def _delete_zip_file_if_requested(self, target_dir, target_file_name):
        if self._remove_zip_file:
            remove_zip_file = "rm -f '{target_dir}/{target_file_name}'".format(
                target_dir=target_dir,
                target_file_name=target_file_name)
            self._local_executor.execute(remove_zip_file.encode())

    def _extract_pcap_files(self, target_dir, target_file_name):
        unzip_command = (
            r"export LC_ALL=$LANG ; "
            r"cd '{target_dir}' ; "
            r"for i in $(unzip -p {target_file_name} snapshot_file_list.txt | "
            r"perl -0nE'for(/^(\S.*?)^$/gms){{/pcap/&&say/(^\S+zip)/}}') ; "
            r"do unzip {target_file_name} $i ; "
            r"busybox unzip $i '*pcap*' ; {uncompress_command} ; rm $i ; done").format(
            target_dir=target_dir,
            target_file_name=target_file_name,
            uncompress_command=self.uncompress_command)
        self._local_executor.execute(unzip_command.encode())
        stdout, _, _ = self._local_executor.raw_execute(
            "cd '{target_dir}' ; ls -1 *.pcap".format(target_dir=target_dir).encode())
        filenames_list = stdout.decode().splitlines()
        logger.debug("pcap files found and extracted from zip are {}".format(filenames_list))
        return filenames_list

    def _teardown(self):
        self.stop()


class SbtsInterfaceMirroringL1L2BIPCollector(InterfaceMirroringL1L2BIPCollectorBase, CommonOamCollector):
    """
    To Start , Stop and Collect L1/L2 BIP logs on given configuration.
    This collector uses ADMIN API.
    """

    uncompress_command = 'unxz *.xz'

    def __init__(self,
                 destination="Local",
                 target_file_name=None,
                 merge_pcap_files=True,
                 parallel_mirroring=None,
                 mirroring_filter=None,
                 specific_message_ids=None,
                 **kwargs):
        super(SbtsInterfaceMirroringL1L2BIPCollector, self).__init__(**kwargs)
        self._detailed_output = False
        self._interface_mirroring_start_params.update({
            "operation": "Start",
            "destination": destination,
            "detailed_output": self._detailed_output
        })
        if parallel_mirroring is not None:
            self._interface_mirroring_start_params['parallel_mirroring'] = parallel_mirroring
        if mirroring_filter is not None:
            self._interface_mirroring_start_params['mirroring_filter'] = mirroring_filter
        if specific_message_ids is not None:
            self._interface_mirroring_start_params['specific_message_ids'] = specific_message_ids
        self._merge_pcap_files = merge_pcap_files
        self._target_file_name = target_file_name if target_file_name \
            else "{name}.zip".format(name=self._name)

    def _setup(self):
        if self._nr_phy_cell_ids:
            bts_info = self._managed_admin_connection.get_bts_info()
            phycellid_celldns_dict = {
                nr_cell["physicalCellId"]: nr_cell["id"]["internal"]
                for nr_cell in bts_info["cells"]["nr"]}
            self._interface_mirroring_start_params['nr_cell_dns'] = [phycellid_celldns_dict[id]
                                                                     for id in self._nr_phy_cell_ids]
        try:
            self._stop()
            logger.debug("Interface Mirroring Stop call successfully executed, i.e. another BIP trace was running.")
        except Exception:
            pass

    def _start(self):
        self._managed_admin_connection.interface_mirroring(**self._interface_mirroring_start_params)

    def _stop(self):
        self._managed_admin_connection.interface_mirroring(operation='Stop')

    def _collect(self, target_dir):
        self._managed_admin_connection.collect_mirroring_logs(
            output_file_name=os.path.join(target_dir, self._target_file_name),
            timeout=self._timeout,
            detailed_output=self._detailed_output)
        filenames_list = self._extract_pcap_files(target_dir, self._target_file_name)
        if self._merge_pcap_files:
            pcap_files = collections.defaultdict(list)
            for input_filename in filenames_list:
                if re.search(r"Z\d+\.pcap$", input_filename):
                    output_filename = re.sub(
                        r"Z\d+\.pcap",
                        r"Z.pcap",
                        input_filename)
                    pcap_files[output_filename].append(input_filename)
            for output_filename in sorted(pcap_files.keys()):
                input_filenames_list = pcap_files[output_filename]
                merge_pcap_files_command = (
                    "cd '{target_dir}' ; "
                    "mergecap -w '{output_filename}' {input_filenames_string} && "
                    "rm -f {input_filenames_string}".format(
                        target_dir=target_dir,
                        output_filename=output_filename,
                        input_filenames_string=" ".join(
                            "'{}'".format(input_filename)
                            for input_filename in input_filenames_list)))
                self._local_executor.execute(merge_pcap_files_command.encode())
        self._delete_zip_file_if_requested(target_dir, self._target_file_name)


class AirphoneL1L2BIPCollector(ScriptInstallationMixin, L1L2BIPCollectorBase):
    """
    Decorating collector to enable port mirroring for L1/L2 BIP tracing on Airphone via shell script(s).
    """

    def __init__(
            self,
            script_paths,
            command_line=None,
            **kwargs):
        super(AirphoneL1L2BIPCollector, self).__init__(**kwargs)
        self.script_paths = script_paths
        self._teardown_command = None
        if command_line is None:
            self._setup_command = './' + os.path.basename(self.script_paths[0])
        elif isinstance(command_line, basestring):
            self._setup_command = command_line
        else:
            self._setup_command = command_line['setup']
            self._teardown_command = command_line.get('teardown')

    def _build_setup_command(self):
        return "cd {script_dir} ; {command_line}".format(
            script_dir=self._script_dir,
            command_line=self._setup_command).encode()

    def _build_teardown_command(self):
        if self._teardown_command is not None:
            return "cd {script_dir} ; {command_line}".format(
                script_dir=self._script_dir,
                command_line=self._teardown_command).encode()


class VduInterfaceMirroringL1L2BIPCollector(InterfaceMirroringL1L2BIPCollectorBase, VduCollector):
    """
    To Start , Stop and Collect L1/L2 BIP logs on given configuration.
    This collector uses VDU OAMCU REST API via taf.gnb.oam.coam.vdu.
    """

    uncompress_command = 'gunzip *.gz'

    def _wait_until_status(self, target_status):
        last_result = None
        start_time = time.time()
        while True:
            if time.time() - start_time > self._timeout:
                raise RuntimeError(f"target status {target_status!r} not reached within {self._timeout} "
                                   f"seconds: current status {last_result!r}")
            result = self._managed_vdu_connection.get_interface_mirroring_information()['operationStatus']
            if result != last_result:
                last_result = result
                logger.debug(f"current status: {result}")
            if result in target_status:
                return result
            if result == "failed":
                raise RuntimeError("api operation failed.")
            time.sleep(0.1)

    def _setup(self):
        if self._nr_phy_cell_ids:
            cell_objects = self._managed_vdu_connection.get_current_plan_objects(
                class_name=["NRCELL"], timeout=self._timeout).to_dict()["objects"]
            phycellid_celldns_dict = {json.loads(cell_object["json_repr"])['physCellId']: cell_object["distName"] for
                                      cell_object in cell_objects}
            self._interface_mirroring_start_params['nr_cell_dns'] = [phycellid_celldns_dict[id]
                                                                     for id in self._nr_phy_cell_ids]
        try:
            self._stop()
            logger.debug(
                "Vdu Interface Mirroring inactive call successfully executed, i.e. another BIP trace was running.")
        except Exception:
            pass

    def _start(self):
        self._managed_vdu_connection.update_interface_mirroring_configuration(usage_state='active',
                                                                              **self._interface_mirroring_start_params)
        self._wait_until_status("succeeded")

    def _stop(self):
        self._managed_vdu_connection.update_interface_mirroring_configuration(usage_state='inactive')
        self._wait_until_status("succeeded")

    def _collect(self, target_dir):
        log_path = self._managed_vdu_connection.get_local_snapshot(directory=target_dir, compressed_or_not=True,
                                                                   filter_regx='mirroring')
        target_file_name = os.path.basename(log_path)
        self._extract_pcap_files(target_dir, target_file_name)
        self._delete_zip_file_if_requested(target_dir, target_file_name)
